import std.io

pub type AppError = Failed(String)

record Point { x: Int64, y: Int64, label: String }

fn shift(p: Point) -> Point {
    return Point { x: p.x + 10 with &p }
}

pub fn main() effect io -> Result<(), AppError> {
    let p = Point { x: 1, y: 2, label: "p" }
    let q = Point { x: 3 with &p }
    io.println("${p.x} ${p.y} ${q.x} ${q.y} ${q.label}")
    let r = shift(q)
    io.println("${r.x} ${r.y} ${r.label}")
    return Ok(())
}
